function f = HS23_f(x)
f = x(1).^2 + x(2).^2;
end

function g = HS23_g(x)
g = zeros(2, 1);
g(1) = 2*x(1);
g(2) = 2*x(2);
end

function c = HS23_c(x)
c = zeros(5, 1);
c(1) = x(1) + x(2) - 1;
c(2) = x(1).^2 + x(2).^2 - 1;
c(3) = 9*x(1).^2 + x(2).^2 - 9;
c(4) = x(1).^2 - x(2);
c(5) = -x(1) + x(2).^2;
end

function J = HS23_J(x)
J = zeros(5, 2);
J(1, 1) = 1;
J(1, 2) = 1;
J(2, 1) = 2*x(1);
J(2, 2) = 2*x(2);
J(3, 1) = 18*x(1);
J(3, 2) = 2*x(2);
J(4, 1) = 2*x(1);
J(4, 2) = -1;
J(5, 1) = -1;
J(5, 2) = 2*x(2);
end
